import{_ as l,o as t,c as e,a2 as i}from"./chunks/framework.C-si7TFR.js";const u=JSON.parse('{"title":"完成第一个任务","description":"安全启动 IOLinker，连接模型，完成第一次对话并创建一个可视化工作流。","frontmatter":{"title":"完成第一个任务","description":"安全启动 IOLinker，连接模型，完成第一次对话并创建一个可视化工作流。"},"headers":[],"relativePath":"zh/guide/quick-start.md","filePath":"zh/guide/quick-start.md"}'),r={name:"zh/guide/quick-start.md"};function o(n,a,s,h,d,c){return t(),e("div",null,[...a[0]||(a[0]=[i('<h1 id="完成第一个任务" tabindex="-1">完成第一个任务 <a class="header-anchor" href="#完成第一个任务" aria-label="Permalink to &quot;完成第一个任务&quot;">​</a></h1><p>这条路径不依赖旧机器人触发器。先完成一个能在页面中检查结果的小任务，再考虑定时、远程访问或业务系统集成。</p><h2 id="_1-启动并完成安全初始化" tabindex="-1">1. 启动并完成安全初始化 <a class="header-anchor" href="#_1-启动并完成安全初始化" aria-label="Permalink to &quot;1. 启动并完成安全初始化&quot;">​</a></h2><ol><li>从<a href="https://iolinker.com/#cta" target="_blank" rel="noreferrer">官网下载区</a>选择与操作系统、CPU 架构匹配的安装包；不要仅凭“NAS”名称选择架构。</li><li>按启动程序的实际输出打开本地 Web 地址。端口以启动日志为准。</li><li>完成首次登录，并立即通过账户菜单修改初始密码。文档不提供或建议固定默认凭证。</li><li>未完成账户安全配置前，不要向公网开放服务，也不要分享 Cookie、令牌或配置文件。</li></ol><p>详细边界见<a href="./deployment.html">安装与部署</a>。</p><h2 id="_2-连接一个模型" tabindex="-1">2. 连接一个模型 <a class="header-anchor" href="#_2-连接一个模型" aria-label="Permalink to &quot;2. 连接一个模型&quot;">​</a></h2><ol><li>在 Agent 工作台打开对话；没有可用模型时，页面会显示模型配置提示。</li><li>通过提示中的<strong>快速配置</strong>或<strong>模型设置</strong>入口，选择服务商并填写其要求的模型名称、接口地址和 API Key。</li><li>保存并回到对话，确认模型状态已可用，再创建或选择 Agent。</li><li>保留必要的工具选择，先不授权文件、命令或远程通道。</li></ol><p>模型服务通常由第三方提供。发送给模型的提示词、会话、检索片段和工具数据可能传输到服务商；请先确认数据是否适合发送。保存配置不等于已建立网络连通或余额可用。</p><h2 id="_3-完成第一次对话" tabindex="-1">3. 完成第一次对话 <a class="header-anchor" href="#_3-完成第一次对话" aria-label="Permalink to &quot;3. 完成第一次对话&quot;">​</a></h2><ol><li>创建 Agent 后进入其对话页面。</li><li>输入一个明确的小任务，例如：<code>总结这个 Agent 可以调用的能力，并告诉我哪些操作需要额外授权。</code></li><li>等待流式回答，检查返回的工具卡片、异常信息和任务结果。</li><li>打开会话列表，确认该会话已保存；在对应入口查看链路，区分 Agent 会话与定时任务。</li></ol><p><strong>完成标准：</strong> 页面出现可阅读的回答，且没有模型鉴权或工具权限错误。不要仅凭“请求已发送”判断任务完成。</p><h2 id="_4-创建第一个工作流" tabindex="-1">4. 创建第一个工作流 <a class="header-anchor" href="#_4-创建第一个工作流" aria-label="Permalink to &quot;4. 创建第一个工作流&quot;">​</a></h2><ol><li>切换到工作流模式，使用<strong>新建</strong>按钮创建空白流程。</li><li>保留<strong>手动触发器</strong>，添加一个 <a href="./../llm.html">LLM 节点</a>，按界面要求选择模型凭据和输入。</li><li>将结果连接到<a href="./../output.html">流程输出</a>，保存流程并手动执行。</li><li>打开执行记录，检查各节点状态、输入输出和失败原因。</li></ol><p><strong>完成标准：</strong> 流程有明确的完成状态，输出与任务相符。第一次运行失败时先修正模型与节点配置，不要直接增加无人值守执行。</p><h2 id="_5-再逐步扩展" tabindex="-1">5. 再逐步扩展 <a class="header-anchor" href="#_5-再逐步扩展" aria-label="Permalink to &quot;5. 再逐步扩展&quot;">​</a></h2><ul><li>希望 Agent 协助生成或修改流程：阅读<a href="./workflows.html">工作流与排障</a>。</li><li>希望定时执行：阅读 <a href="./schedules.html">Agent 定时任务</a>，区分它与工作流 Crontab。</li><li>希望接入内部资料：先阅读<a href="./knowledge.html">知识库与检索</a>，确认模型配置。</li><li>希望使用表单和人工确认：阅读<a href="./forms.html">表单与协作</a>。</li></ul><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><ul><li><strong>没有模型可选：</strong> 检查模型配置、当前项目与服务商设置；当前指南不假设所有部署预置模型。</li><li><strong>任务一直等待：</strong> 检查工具授权、模型响应和任务状态；不要把长耗时误认为成功执行。</li><li><strong>找不到旧机器人菜单：</strong> 旧触发器的新建入口已从当前节点菜单中隐藏。</li><li><strong>安装包与文档不同：</strong> 文档按当前源码界面核对，以安装包实际界面为准，不宣称所有旧版本具备这些能力。</li></ul>',18)])])}const _=l(r,[["render",o]]);export{u as __pageData,_ as default};
